import re

def parse(lines):
    env = []
    envl = []
    cont = []
    contl = []
    skip = []
    sec = ''
    sub = ''
    top = ''
    infence = False
    lang = ''
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        if not infence:
            m = re.match(r'^(#{2,})\s+(.*\S)', l)
            if m:
                if len(m.group(1)) == 2:
                    sec = m.group(2)
                    sub = ''
                else:
                    sub = m.group(2)
                top = ''
                skip.append(i)
                continue
        if l.startswith('```'):
            if not infence:
                lang = l[3:].strip()
                top = ''
            infence = not infence
            skip.append(i)
            continue
        name = sec + (' / ' + sub if sub else '')
        m = None
        if infence and not lang and not re.match(r'^\s*<.*>\s*$', l):
            m = re.match(r'^(?P<ind>\s*)(?P<key>\S(?:.*?\S)?)(?:\s{2,}(?P<value>\S.*?))?\s*$', l)
        if m:
            key = m.group('key')
            val = m.group('value') or ''
            if m.group('ind'):
                grp = top
            else:
                top = key
                grp = ''
            env.append({'Section': name, 'Group': grp, 'Key': key, 'Value': val})
            envl.append(i)
        else:
            cont.append({'Section': name, 'Line': l.strip()})
            contl.append(i)
    blocks = []
    if env:
        blocks.append({'name': 'settings', 'kind': 'table', 'lines': envl, 'records': env})
    if cont:
        blocks.append({'name': 'file_contents', 'kind': 'table', 'lines': contl, 'records': cont})
    return {'blocks': blocks, 'skip': skip}
